import {ToolRegistry} from './registry.js';
import type {ToolResponse} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';

describe('ToolRegistry', () => {
  it('rejects input missing a required property and does not call executor', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn().mockResolvedValue('success');

    registry.register(
      {
        name: 'test_tool',
        description: 'A test tool',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'},
          },
          required: ['location'],
        },
      },
      executor
    );

    const result = (await registry.execute('test_tool', {})) as ToolResponse;

    const calls = executor.mock.calls;

    expect({
      called: calls.length,
      hasLocation: /location/i.test(result.result),
      hasRequired: /required/i.test(result.result),
    }).toEqual({
      called: 0,
      hasLocation: true,
      hasRequired: true,
    });
  });

  it('throws at registration time for an uncompilable schema, naming the tool', () => {
    const registry = new ToolRegistry();
    expect(() =>
      registry.register(
        {
          name: 'bad_tool',
          description: 'A tool with a bad schema',
          inputSchema: {type: 'not-a-type'},
        },
        jest.fn()
      )
    ).toThrow(/bad_tool/);
  });

  it('compiles a static tool schema once across multiple execute calls', async () => {
    const registry = new ToolRegistry();
    let schemaAccesses = 0;

    // A getter on inputSchema allows observing ajv.compile reads.
    const definition = {
      name: 'static_tool',
      description: 'Test static tool',
      get inputSchema() {
        schemaAccesses++;
        return {type: 'object', properties: {a: {type: 'string'}}};
      },
    };

    registry.register(definition as unknown as ToolDefinition, jest.fn().mockResolvedValue('ok'));

    const accessesAfterRegister = schemaAccesses;

    for (let i = 0; i < 10; i++) {
      await registry.execute('static_tool', {});
    }

    expect({initial: accessesAfterRegister > 0, final: schemaAccesses}).toEqual({
      initial: true,
      final: accessesAfterRegister,
    });
  });

  it('validates function-valued definitions against the schema current at that call, not a stale one', async () => {
    const registry = new ToolRegistry();
    let useNumberSchema = true;

    const schemaA = {type: 'object', properties: {val: {type: 'number'}}};
    const schemaB = {type: 'object', properties: {val: {type: 'string'}}};

    registry.register(
      () => ({
        name: 'dynamic_tool',
        description: 'Changes schema',
        inputSchema: useNumberSchema ? schemaA : schemaB,
      }),
      jest.fn().mockResolvedValue('ok')
    );

    const res1 = (await registry.execute('dynamic_tool', {val: 42})) as ToolResponse;
    const res2 = (await registry.execute('dynamic_tool', {val: 'foo'})) as ToolResponse;
    useNumberSchema = false;
    const res3 = (await registry.execute('dynamic_tool', {val: 'foo'})) as ToolResponse;
    const res4 = (await registry.execute('dynamic_tool', {val: 42})) as ToolResponse;

    expect({
      res1: res1.result,
      res2IsError: /validation failed/i.test(res2.result),
      res3: res3.result,
      res4IsError: /validation failed/i.test(res4.result),
    }).toEqual({
      res1: 'ok',
      res2IsError: true,
      res3: 'ok',
      res4IsError: true,
    });
  });

  it('passes valid input with an unlisted extra property through to the executor unchanged', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn().mockResolvedValue('ok');
    registry.register(
      {
        name: 'extra_tool',
        description: 'Tool',
        inputSchema: {
          type: 'object',
          properties: {req: {type: 'string'}},
        },
      },
      executor
    );

    await registry.execute('extra_tool', {req: 'value', extra: 'bonus'});
    expect(executor).toHaveBeenCalledWith({req: 'value', extra: 'bonus'}, undefined);
  });

  it('rejects wrong-typed field with expected type and does not leak offending value', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'type_tool',
        description: 'Tool',
        inputSchema: {
          type: 'object',
          properties: {count: {type: 'number'}},
        },
      },
      jest.fn()
    );

    const res = (await registry.execute('type_tool', {count: 'not-a-number'})) as ToolResponse;
    const msg = res.result;

    expect({
      hasPath: /count/.test(msg),
      hasType: /number/.test(msg),
      hasValue: /not-a-number/.test(msg),
    }).toEqual({
      hasPath: true,
      hasType: true,
      hasValue: false,
    });
  });

  it('throws Unknown tool: <name> for unregistered name', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('nope', {})).rejects.toThrow('Unknown tool: nope');
  });

  it('produces no log line containing an identifying offending value when rejected', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'log_tool',
        description: 'Tool',
        inputSchema: {
          type: 'object',
          properties: {id: {type: 'number'}},
        },
      },
      jest.fn()
    );

    const logs: any[] = [];
    const {log} = await import('../../shared/logger.js');
    const spy = jest.spyOn(log, 'warn').mockImplementation((...args) => {
      logs.push(args);
    });

    await registry.execute('log_tool', {id: 'SECRET_12345'});

    spy.mockRestore();

    const allLogsStr = JSON.stringify(logs);
    expect(allLogsStr.includes('SECRET_12345')).toBe(false);
  });
});

import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';
import AjvModule, {ValidateFunction, ErrorObject} from 'ajv';

const Ajv = (AjvModule as unknown as {default: typeof AjvModule}).default || AjvModule;

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validate?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private readonly ajv = new (Ajv as any)({strict: false});
  private readonly schemaCache = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    if (typeof definition === 'function') {
      this.tools.set(definition().name, {definitionSource: definition, execute});
      return;
    }

    try {
      const validate = this.ajv.compile(definition.inputSchema);
      this.tools.set(definition.name, {definitionSource: definition, execute, validate});
    } catch (err: unknown) {
      throw new Error(
        `Failed to compile schema for tool ${definition.name}: ${err instanceof Error ? err.message : String(err)}`,
        {cause: err}
      );
    }
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Executes a tool, validating its input against its registered schema. Returns a rejection ToolResponse if invalid. ([validated by specs/hal-engine-tool-input-validation/spec.md]) */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }

    let validate = tool.validate;
    if (!validate) {
      const definition = this.resolveDefinition(tool.definitionSource);
      validate = this.schemaCache.get(definition.inputSchema);
      if (!validate) {
        validate = this.ajv.compile(definition.inputSchema) as ValidateFunction;
        this.schemaCache.set(definition.inputSchema, validate);
      }
    }

    const isValid = validate!(input);
    if (!isValid) {
      const errorList = validate!.errors ?? [];
      const errors =
        errorList
          .map((e: ErrorObject) => {
            const path = 'instancePath' in e ? e.instancePath : 'dataPath' in (e as unknown as {dataPath: string}) ? (e as unknown as {dataPath: string}).dataPath : '';
            return `${String(path)} ${e.message}`;
          })
          .join(', ') || 'Unknown validation error';
      log.warn('tool', 'validation failed', {name, inputKeys: Object.keys(input), errors});
      return {result: `Input validation failed: ${errors}`};
    }

    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

